from author import C,M,P,S

c=C('课程导学与程序结构')
S(c,'课程知识总览','',[
 P([], '同学们好，欢迎来到一小时学习 Go 基础语法。这一页列出了本课要掌握的内容。我们先认识变量、常量和数据类型，知道怎样保存姓名与成绩。再用运算符完成计算，通过输入输出和使用程序的人交流。接着用分支处理不同情况，用循环重复执行步骤。数组与切片保存一组数据，映射和字符串帮助我们查询信息、处理文字。'),
 P([], '在这些基础上，我们会用函数组织步骤，认识多返回值和延迟执行；再通过指针与结构体理解怎样传递和修改数据。最后认识方法、接口和包，学习 Go 怎样明确处理错误，并把知识连成一个学生成绩小程序。课程从零开始，每次先看具体代码和运行结果，再总结规则。遇到练习先预测，四秒后一起核对。先把基础语法走清楚，再学习并发和网络开发。')],['变量、常量、类型与输入输出','分支循环、数组切片、映射字符串','函数、指针结构体、方法接口与错误'])
S(c,'第一个 Go 程序','''package main
import "fmt"
func main() {
    fmt.Println("你好，Go")
}''',[
 P([1,2], '先看一个完整的小程序。第一行说明这份文件属于 main 包，main 包用于构建可以启动执行的程序。包可以先理解为把相关代码组织在一起的方式。第二行引入 fmt，它是 Go 自带的工具包，提供显示文字等功能。这里不是随便给程序加两句装饰，而是在说明代码属于哪里，以及接下来要使用哪一套现成工具。'),
 P([3,4], 'func 表示定义函数，main 是程序开始执行的位置。大括号里的 Println 会显示括号中的内容，并在输出后换行。所以结果是你好，Go，双引号本身不会显示。源文件通常以点 go 结尾。本课把这份文件叫 main.go。平时每条语句放一行，不需要自己在行尾加分号；函数这一行的左大括号要和函数头放在同一行，不要按其他语言习惯另起一行。',True)],['package 声明所属的包','import 引入需要的工具','main 函数是启动入口'],'你好，Go')
code=M('fmt.Print("你好")\nfmt.Println("，小林")\nfmt.Println(80 + 5)')
S(c,'练习：文字还是计算',code,[P([2,3,4], '请预测这个程序会显示几行，每一行是什么。第一句使用 Print，第二句使用 Println，最后一句的算式没有放在双引号里。先不要根据源代码有几行，就判断结果也一定有几行。需要分别考虑输出以后是否换行，以及小括号里面究竟是文字还是要计算的数值。现在独立想四秒。')],['Print 输出后不自动换行','引号区分文字与算式'],kind='question',answer='你好，小林\n85')
S(c,'答案：按顺序执行每一步',code,[
 P([2,3], '前两句合起来显示你好，小林。Print 只负责输出，后面的 Println 接在同一行继续输出，然后才换行。程序会按这里写出的顺序执行，不会自己调换两次输出。你可以把第一句也改成 Println，看看问候语怎样分到两行。看结果有变化，再回头解释哪条规则造成变化，是很好的入门练习方法。',True),
 P([4], '最后显示八十五。没有引号的加法会先计算，再交给输出函数；把整个算式放进双引号，就只是显示文字。这份程序可以使用 go run main.go 运行，也可以先用 go build 构建，再启动生成的程序。代码格式可以交给 gofmt 整理，但格式工具不会替你改正业务逻辑。以后读每个例子，都先问它保存什么、执行哪些步骤、最后得到什么结果。',True)],['先执行前面的语句','无引号的算式先计算','运行、构建与格式整理各有用途'],'你好，小林\n85')

c=C('变量常量与数据类型')
S(c,'给数据起一个名字',M('var name string = "小林"\nvar score int = 80\nfmt.Println(name)\nfmt.Println(score)'),[
 P([2,3], '假设程序要多次使用一个学生的姓名和成绩，每次直接写小林和八十，很难看出数据的用途。我们可以给它们起名字。var 表示声明变量，后面先写变量名，再写类型，等号右边是最初保存的值。name 保存姓名，score 保存成绩。等号在这里表示赋值，不是数学中要求左右两边永远相等的等式。'),
 P([4,5], '下面输出 name 和 score 时，没有给变量名加双引号，所以程序取出里面保存的内容，分别显示小林和八十。若写成引号里的 score，就只会显示这个英文单词。变量名尽量说明含义，例如总分、人数和平均分，不要全部用没有含义的单个字母。名字、类型和当前的值是三件不同的事，先把它们分清楚，后面读程序就容易很多。',True)],['变量保存数据，名字表达用途','Go 把类型写在名字后面','使用变量名取出当前值'],'小林\n80')
S(c,'类型推断与短变量声明',M('var name = "小林"\nscore := 80\nscore = 85\nfmt.Println(name, score)'),[
 P([2,3], '右边已经提供一个值时，Go 往往可以判断类型，所以 var name 后面省略了 string。函数里面还有一种常见写法：冒号加等号，同时声明变量并给它初始值。这里 score 根据八十被推断为整数类型。短变量声明只能写在函数内部，不能直接放在包的最外层。写得短不等于取消了类型检查。'),
 P([4,5], '第三个步骤把已有成绩改成八十五，用的是普通等号。因为我们是在更新已有变量，不是在同一层再声明一遍。Println 可以接收多个值，它会用空格把这里的姓名和成绩分开显示。初学时要特别留意有没有冒号：同样看起来是在给数据取名字，声明新变量和修改旧变量却不是同一个动作。这个差异在嵌套代码块里还会影响变量的作用范围。',True)],['有初始值时可以推断类型',':= 在函数内声明并赋初值','= 修改已经存在的变量'],'小林 85')
S(c,'没有显式赋值时的零值',M('var score int\nvar passed bool\nvar name string\nfmt.Printf("%d %t %q\\n", score, passed, name)'),[
 P([2,3,4], '声明变量时，如果已经写明类型，也可以暂时不提供初始值。Go 会给它对应的零值。整数的零值是零，布尔值是 false，字符串是空字符串。这不是一块没有规则的随机内容。零值让许多简单数据可以先声明，再根据后续步骤更新，不过零值是不是符合业务含义，仍然需要你自己判断。'),
 P([5], '这里用格式化输出把三项放到一行。先观察结果：零、false 和一对空双引号。带引号的空字符串方便我们看出，它确实没有字符，而不是输出漏掉了。百分号后面的字母是输出格式，下一章会专门练习。现在先记住，零分可能是真实成绩，如果还需要表达尚未录入，就不能只靠一个默认的零来区分。',True)],['整数、布尔、字符串各有零值','零值不是随机内容','零值不一定等于业务上的缺失'],'0 false ""')
S(c,'常量表示不应改变的值',M('const passScore = 60\nscore := 85\nfmt.Println(score >= passScore)\nconst message = "成绩已保存"\nfmt.Println(message)'),[
 P([2,3,4], '及格线通常是本次规则中的固定值，可以用 const 声明常量。这样写能告诉读者，这里不是准备在运行过程中反复修改的数据。比较成绩时使用 passScore，比在很多位置都直接写六十，更容易看清数字的含义。常量也不是只能保存数字，下面的消息文字同样可以声明为常量。'),
 P([5,6], '运行后先得到 true，再显示成绩已保存。常量不能像普通变量一样重新赋值，而且常量的值要满足编译期能够确定等规则，不能把任意一次函数调用的结果都随手变成 const。初学先使用明确的数字和文字常量，不展开常量表达式的细节。命名固定规则的好处，是以后修改需求时更容易找到应当调整的地方。',True)],['const 声明常量','常量不能重新赋值','固定规则应取有含义的名字'],'true\n成绩已保存')
S(c,'常见基本类型',M('count := 3\naverage := 86.5\npassed := true\nletter := \'A\'\nfmt.Println(count, average, passed)\nfmt.Printf("%c %d\\n", letter, letter)'),[
 P([2,3,4], '数据除了有名字，还分种类。人数常用 int 保存整数，平均分常用 float64 保存小数，是否及格用 bool 保存真或假。这里都依靠右边的值推断类型。带小数点的普通数值会推断成 float64，true 和 false 没有双引号，它们不是两段普通文字。类型帮助编译器判断哪些操作可以执行。'),
 P([5,6,7], '单引号里的 A 表示一个字符对应的码点值，这里推断为 rune。你会看到按字符方式显示是 A，按整数方式显示是六十五。rune 用来处理 Unicode 码点，后面字符串一章再结合中文解释。双引号则保存字符串。Go 还提供不同宽度的整数和浮点数，入门先把 int、float64、bool、string 与 rune 用清楚，不必第一次就背完所有名字。',True)],['int、float64、bool 用于常见数据','双引号表示字符串','rune 可表示 Unicode 码点'],'3 86.5 true\nA 65')
S(c,'转换与作用范围',M('total := 251\ncount := 3\naverage := float64(total) / float64(count)\nfmt.Println(average)'),[
 P([2,3,4], '三个人的总分是二百五十一，要算带小数的平均分，就先把两个整数转换成 float64，再进行除法。类型名后面的小括号，在这里表示转换。Go 不会在任意整数和小数之间都自动替你完成混合计算，要求不同类型配合时，要明确写出意图。转换得到新值，并不会永久改变原来 total 和 count 的类型。'),
 P([5], '结果带有小数。变量能在哪些位置使用，还受到它声明范围的限制。函数内部声明的普通局部变量，不能直接拿到另一个函数里用。Go 也会检查声明后没有使用的普通局部变量，所以随手保存一个值却一直不用，可能会阻止编译。不要为了绕过提醒就乱删代码，先判断这份数据是否真的需要，或者是不是漏掉了使用它的步骤。',True)],['参与计算前明确转换类型','转换不会改写原变量类型','局部变量有自己的使用范围'],'83.66666666666667')
code=M('score := 80\nscore = "优秀"\nfmt.Println(score)')
S(c,'练习：变量能随时换类型吗',code,[P([2,3], '这段程序想把分数换成评价文字。请判断它能不能通过编译。score 的声明没有直接写 int，是不是就意味着它以后可以保存任意类型？这里问的是能否编译，不是评价文字是否好看。请先确认最初的值让 Go 推断出了什么类型，再看第二次赋值是不是符合要求。')],['类型推断不等于没有类型','先判断能否通过编译'],kind='question',mode='compile_error',diagnostic='cannot use')
S(c,'答案：分数和评价分别保存',M('score := 80\nlabel := "优秀"\nfmt.Println(score, label)'),[
 P([2,3], '原题不能通过编译。score 根据初始值被推断为 int，并不是一个可以随时更换类型的容器。把文字直接赋给它，不符合这个变量的类型要求。左边展示一种更清楚的修正：分数仍然放在 score，评价另外放在 label。它们有不同含义，本来就适合分开保存。',True),
 P([4], '现在输出八十和优秀。不要把 Go 的冒号等号理解成动态类型开关，也不要因为某个错误消失了，就认为业务建模一定正确。我们始终先看数据含义，再选择类型和操作。到这里，变量、常量、初始值、零值和类型转换已经有了具体印象。下一章让数据参与计算，并学习怎样把输入和输出写得更清楚。',True)],['原题是编译错误','变量的类型不会随意变化','不同含义的数据分开命名'],'80 优秀')
